#!/bin/zsh
# Saison 2, chapitre 16 (le Choixseau) : file de génération (grande salle, cachot des potions, chapeau, seau, professeur,
# chauve-souris, chouette, élève, bougies, objets). Les bougies flottantes et la neige sont faites par le moteur (sprites, particules).
cd "$(dirname "$0")/.." || exit 1; mkdir -p work/s2play/items work/s2play/persos work/s2play/ltx
PS="${PS:-work/crossover/persos}"; HS="${HS:-work/crossover/hero_s2}"
ST="hand-painted 2000s 2D point-and-click adventure game background, painterly detailed backgrounds like classic adventure games, bold dark outlines, saturated colors, humorous storybook fantasy, wide establishing shot at eye level, empty scene with no people, no logo, no coat of arms, no watermark, no frame, no text, no letters, no writing"
IT="single game item, hand-painted 2D point-and-click adventure game art of the early 2000s, detailed painterly shading, bold dark outlines, saturated colors, the whole object visible with a margin, plain flat solid magenta background, no shadow, no text, no letters"
H="A huge medieval castle great hall at night seen from its center aisle: four very long wooden dining tables with benches run from the foreground to the back on both sides, set with golden plates and goblets, nobody seated; at the back, a raised wooden high table for the teachers in front of a tall gothic stained-glass window with plain colored diamond panes; tall stone walls with gothic arches and simple colored banners without any emblem; the ceiling is open onto a deep blue starry night sky with a few soft clouds, as if enchanted; NO candles anywhere, no candlesticks, no torches, the hall is lit by a warm golden glow; the polished wooden floor of the center aisle fills the whole lower third of the picture, flat and walkable from left to right. Nobody. $ST"
for sd in 1 2 3; do out="work/s2play/d_hall_$sd.png"; [ -f "$out" ] || flux-image "$H" -i crossover/img/r_potter.jpg -s 1280x720 --seed $sd -o "$out"; done
D="A medieval castle dungeon classroom for potions, seen from the front: low vaulted stone ceiling with thick arches, a big black iron cauldron on three feet stands left of center over a small glowing wood fire, wooden shelves on the walls crowded with glass jars, dried herbs, skulls of small animals and colored potion bottles, two long wooden workbenches with small cauldrons and scales at the back, a big wooden desk with books and a candle on the right for the teacher, greenish light from a high barred window and warm firelight; the stone floor fills the whole lower third of the picture, flat and walkable from left to right. Nobody. $ST"
for sd in 1 2 3; do out="work/s2play/d_potions_$sd.png"; [ -f "$out" ] || flux-image "$D" -s 1280x720 --seed $sd -o "$out"; done
i(){ out="work/s2play/items/$1_$2.png"; [ -f "$out" ] || flux-image "$3 $IT" -s 1024x768 --seed $2 -o "$out"; }
for sd in 1 2; do
  i p_stool16 $sd "one small old three-legged wooden stool, seen slightly from above in three-quarter view."
  i p_candle16 $sd "one single tall white wax candle without any holder, lit, a bright warm flame, drops of melted wax running down its side, standing upright."
  i p_fcheese16 $sd "one small round wheel of golden yellow cheese with a dark rind, seen slightly from the side."
  i i_flower16 $sd "one small sprig of blue mountain flower with five pointed bright blue petals and a yellow heart on a short green stem with a few leaves, like a wild alpine flower."
  i i_cheese16 $sd "one big festive round wheel of golden cheese on a silver platter, a red ribbon with a bow tied around it, a little sprig of holly on top."
done
f(){ out="work/s2play/persos/$1_$2.png"; [ -f "$out" ] || flux-image "$3 The whole figure visible with a margin, plain flat solid magenta background, no shadow, no ground, no text." -i "$4" -s 1024x1280 --seed $(( $5 + $2 )) -o "$out"; }
for sd in 1 2; do
  f bucket16 $sd "The same grumpy talking face as on the old hat of the reference picture, same sour expression with heavy eyelids and pouting mouth, but now on an old wooden bucket with dark iron bands: the face is formed by the bent and dented wood planks, the bucket stands upright, seen from the front, in the same painted style." $PS/c_hat.png 1600
  f hero_sort16 $sd "Exactly the same character as in the reference picture, same face, same horned iron helmet, same armor, kilt and boots, now sitting on a small three-legged wooden stool, hands on his knees, a proud happy smile, and an old wooden bucket with dark iron bands perched upright on top of his helmet between the horns, the bucket has a grumpy talking face made of bent wood planks, seen from the front." $HS/sel_front.png 1610
  f bat16 $sd "Exactly the same sour sneering pale face and long greasy black hair as the professor of the reference picture, but he is now a small black bat with leathery wings spread wide, the same contemptuous expression on its tiny face, flying, seen from the front." $PS/c_potions2.png 1620
  f owl16 $sd "A brown and white barn owl perched on a tall wooden perch stand with a round base, calm and dignified, big dark eyes, seen in three-quarter view facing left, in the same painted style as the reference picture." $PS/c_hat.png 1630
  f chicken16 $sd "A plump white farm hen perched on a tall wooden perch stand with a round base, holding a sealed envelope with a red wax seal in its beak, looking proud and silly, seen in three-quarter view facing left, in the same painted style as the reference picture." $PS/c_hat.png 1640
  f student16 $sd "A skinny teenage boy student with messy red hair and freckles, a long black school robe with a grey jumper and a striped red and gold tie, holding up a thin wooden magic wand in his right hand with a nervous proud look, standing, seen in three-quarter view facing right, in the same painted style as the reference picture." $PS/c_potions2.png 1650
done
FIX="CAMERA: static locked-off full shot, the camera never moves, no zoom."
MAG="It keeps exactly the same viewing angle, the same face and the same look for the whole shot. ENV: plain flat solid magenta background, perfectly uniform, no ground, no shadow, no scenery."
l(){ out="work/s2play/ltx/$1.mp4"; [ -f "$out" ] || video-locale "$FIX SUBJECT: $2 ACTION: $3 $MAG" -o "$out" -d $4 -s 768x960 -i "$5" -i "$5" --seed $6 -- --no-audio >/dev/null 2>&1 && echo "ok $1"; }
l hat_i "the old patched talking hat of the image, alive." "it stays in place and breathes slowly: the cloth swells and settles, the heavy eyelids blink, the eyes glance sideways with suspicion, the pointed tip sways a little, then it comes back to the starting pose." 3 $PS/c_hat.png 1701
l hat_t "the old patched talking hat of the image, alive." "it talks in place: the wide mouth made of a fold of cloth opens and closes clearly as if speaking a line, the eyebrows rise and fall, the pointed tip bends with each word, then it comes back to the starting pose." 2.5 $PS/c_hat.png 1702
l potions_i "the gaunt potions professor of the image." "he stays in place with his arms folded, alive and contemptuous: breathes slowly, blinks, his eyes narrow, he slightly raises his chin and sneers, then comes back to the starting pose." 3 $PS/c_potions2.png 1703
l potions_t "the gaunt potions professor of the image." "he talks slowly in place with his arms folded: the mouth opens and closes clearly as if speaking a line with long pauses, one eyebrow rises, the head tilts slightly, then he comes back to the starting pose." 2.5 $PS/c_potions2.png 1704
echo fini
